//go:build ignore

// Generates mp3tables.go: fixed-point constants, so that decoding itself never
// uses floating point. Run with: go run mp3tables_gen.go > mp3tables.go
package main

import (
	"fmt"
	"math"
)

const one = 1 << 30 // Q30

func q(v float64) int32 { return int32(math.Round(v * one)) }

