	fmt.Println("// Code generated by mp3tables_gen.go; DO NOT EDIT.\n\npackage audiodec\n")
	alias := []float64{-0.6, -0.535, -0.33, -0.185, -0.095, -0.041, -0.0142, -0.0037}
	fmt.Print("var mp3CS = [8]int32{")
	for _, c := range alias {
		fmt.Printf("%d, ", q(1/math.Sqrt(1+c*c)))
	}
	fmt.Print("}\nvar mp3CA = [8]int32{")
	for _, c := range alias {
		fmt.Printf("%d, ", q(c/math.Sqrt(1+c*c)))
	}
	fmt.Println("}")
	var win [4][36]float64
	for i := 0; i < 36; i++ {
		win[0][i] = math.Sin(math.Pi / 36 * (float64(i) + .5))
	}
